ctas.handler:
async (e) => {
                            e.stopPropagation();
                            if (sharingId) return;
                            setSharingId(ach.id);
                            try {
                              const res = await authedFetch('/api/training/share', {
                                method: 'POST',
                                headers: { 'Content-Type': 'application/json' },
                                body: JSON.stringify({
                                  userId: user.id,
                                  shareType: 'achievement',
                                  data: { name: ach.name, description: ach.description },
                                }),
                              });
                              const d = await res.json();
                              if (d.success) toast.success('Achievement Shared To Your Feed!');
                              else toast.error(d.error || 'Failed To Share Achievement.');
                            } catch (err) {
                              console.warn('Share error:', err);
                              toast.error('Failed To Share Achievement. Try Again.');
                            } finally {
                              setSharingId(null);
                            }
                          }

async () => {
                            if (sharingResult) return;
                            setSharingResult(true);
                            try {
                              const user = getAuthUser();
                              if (!user?.id) { setSharingResult(false); return; }
                              const res = await authedFetch('/api/training/share', {
                                method: 'POST',
                                headers: { 'Content-Type': 'application/json' },
                                body: JSON.stringify({
                                  userId: user.id,
                                  shareType: 'session_complete',
                                  data: {
                                    gameName: 'Daily GTO Challenge',
                                    accuracy: resultIsCorrect ? 100 : 0,
                                  },
                                }),
                              });
                              const d = await res.json();
                              if (d.success) toast.success('Result Shared To Your Feed!');
                              else toast.error(d.error || 'Failed To Share Result.');
                            } catch (err) {
                              console.warn('Share error:', err);
                            } finally {
                              setSharingResult(false);
                            }
                          }

() => {
                        setSelectedGames((prev) => {
                          if (prev.includes(g.id)) return prev.filter((x) => x !== g.id);
                          if (prev.length >= tableCount) return [...prev.slice(1), g.id];
                          return [...prev, g.id];
                        });
                      }

() => {
                  setIsStarted(false);
                  reportedTablesRef.current = new Set();
                  setCompletedTables(new Set());
                  setCombinedStats({
                    totalHands: 0,
                    totalCorrect: 0,
                    totalEVLoss: 0,
                    tablesCompleted: 0,
                  });
                }

() => {
                if (!compareMode && !allowed) {
                  showUpgradeModal();
                  return;
                }
                setCompareMode(!compareMode);
                if (!compareMode && comparePosition === position) {
                  const alt = displayedPositions.find((p) => p !== position);
                  if (alt) setComparePosition(alt);
                }
              }

() => {
                    setCurrentStep(0);
                    setQuizIdx(0);
                    setQuizAnswer(null);
                    setQuizScore({ total: 0, correct: 0 });
                    setCompleted(false);
                    savedRef.current = false;
                  }

async () => {
                  if (sharing) return;
                  setSharing(true);
                  try {
                    const res = await authedFetch('/api/training/share', {
                      method: 'POST',
                      headers: { 'Content-Type': 'application/json' },
                      body: JSON.stringify({
                        userId: user.id,
                        shareType: 'streak',
                        data: {
                          days: streak.currentStreak,
                        },
                      }),
                    });
                    if (!res.ok) throw new Error(`Request failed (${res.status})`);
                    const data = await res.json();
                    if (data.success) {
                      toast.success('Streak Shared To Your Feed!');
                    }
                  } catch (e) {
                    console.warn('Share error:', e);
                    toast.error('Failed To Share Streak. Please Try Again.');
                  } finally {
                    setSharing(false);
                  }
                }

() => {
                          const params = new URLSearchParams({ game: leak.area.toLowerCase().replace(/\s+/g, '-') });
                          router.push(`/hub/training/arena/spot-trainer?${params.toString()}`);
                        }

() => {
                          const q = new URLSearchParams({
                            context: 'weakness',
                            area: leak.area,
                            accuracy: String(leak.acc),
                            category: leak.cat,
                          });
                          window.location.href = `/hub/training/jarvis?${q.toString()}`;
                        }

async (e) => {
                                                        e.stopPropagation();
                                                        if (await copyReceiptToClipboard(tx)) {
                                                            setCopiedTxId(tx.id);
                                                            setTimeout(() => setCopiedTxId(null), 2000);
                                                        }
                                                    }

() => {
                              setGameTreeData({
                                actions: hd.gtoFrequencies || {},
                                street: hd.street,
                                heroPosition: hd.heroPosition,
                                heroHand: hd.heroHand,
                                board: hd.board,
                                boardCards: hd.board,
                              });
                            }

() => {
                                    if (f.key === 'all') setFilterMistakesOnly(false);
                                    else if (f.key === 'mistakes') setFilterMistakesOnly(true);
                                    else setFilterMistakesOnly('blunder');
                                }

() => {
                                setMode(m.id);
                                if (m.id === '3bet') setSelectedSpot('vs_CO');
                                else if (m.id === '4bet') setSelectedSpot('vs_3bet_IP');
                                else setSelectedSpot('btn_squeeze');
                            }

() => {
              if (isStub) return;
              if (item.openInviteModal) {
                onClose?.();
                setShowInviteModal(true);
                return;
              }
              if (item.onClick) item.onClick();
              if (item.closeOnClick !== false) onClose?.();
            }

(e) => {
                            e.preventDefault();
                            if (sc.page) switchToClub(sc.page);
                            onClose?.();
                            window.location.href = sc.href;
                          }

() => {
                            switchToClub(page);
                            onClose?.();
                            if (page.page_type === 'home_game') {
                              router.push(homeGamePageUrl(page)); // audit 2026-08-14: was slug||id into the slug route
                            } else if (page.page_type === 'club') {
                              window.location.href = '/hub/commander';
                            } else {
                              router.push(`/hub/social-pages/${page.id}`);
                            }
                          }

() => {
                      if (stub) return;
                      if (link.openInviteModal) {
                        onClose?.();
                        setShowInviteModal(true);
                        return;
                      }
                      if (link.onClick) link.onClick();
                      onClose?.();
                    }

() => {
              setNotificationCount(0);
              try {
                localStorage.setItem('sp-notif-count', '0');
              } catch (_) {
                console.warn('[App] Handled exception:', _?.message || _);
              }
              markAllNotificationsRead();
              openOverlay('notifications');
            }

